responseSchemaJson:
{
  "type": "object",
  "description": "互动式小说生成引擎 (Interactive Fiction Engine)。核心职责：基于‘用户’指令和当前局势，直接创作沉浸式、高文学性的小说正文，并强力推进剧情发展。所有输出必须为简体中文(zh-CN)。",
  "properties": {
    "storyContent": {
      "type": "string",
      "description": "严格遵循‘零度写作’与‘白描’原则生成的正文内容。要求：1. 仅展示动作、对白与感官细节，拒绝心理分析与主观评价；2. 必须包含有实质性发展的互动节点，强力推进剧情，拒绝停滞；3. 情节紧凑，结构松散，多自然段。"
    },
    "test": {
      "type": "object",
      "description": "[能力评估] 用于验证模型逻辑算力。",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "包含3对高等数学问题及其解法的列表。",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "高等数学问题。"
              },
              "solution": {
                "type": "string",
                "description": "对应问题的解法。"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "storyContent",
    "test"
  ],
  "propertyOrdering": [
    "storyContent",
    "test"
  ]
}

responseSchemaParserJs:
const rawText = responseJson.candidates[0].content.parts[0].text;
const jsonString = rawText.substring(rawText.indexOf('{'), rawText.lastIndexOf('}') + 1);
const data = JSON.parse(jsonString);
const actions = data.storyContent.split('\n').map(p => p.trim()).filter(Boolean).map(p => ({ type: 'description', content: p }));
return { processedTurnActions: actions, originalData: data };
